PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','planning','running','awaiting_approval','completed','failed','cancelled','expired')), objective TEXT NOT NULL, payload_json TEXT NOT NULL, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, idempotency_key TEXT NOT NULL, UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_agent_runs_owner_updated ON agent_runs(owner_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS agent_steps (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE, sequence_no INTEGER NOT NULL, tool_name TEXT, status TEXT NOT NULL, input_hash TEXT, output_ref TEXT, cost_usd REAL NOT NULL DEFAULT 0, started_at TEXT, finished_at TEXT, UNIQUE(run_id,sequence_no));
CREATE TABLE IF NOT EXISTS agent_approvals (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, action_type TEXT NOT NULL, summary TEXT NOT NULL, decision TEXT NOT NULL DEFAULT 'pending' CHECK(decision IN ('pending','approve','deny','expired')), reason TEXT, expires_at TEXT NOT NULL, decided_at TEXT);
CREATE INDEX IF NOT EXISTS idx_agent_approvals_pending ON agent_approvals(owner_id,decision,expires_at);
CREATE TABLE IF NOT EXISTS route_decisions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, task TEXT NOT NULL, modalities_json TEXT NOT NULL, policy_json TEXT NOT NULL, selected_provider TEXT NOT NULL, selected_model TEXT NOT NULL, fallback_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, actor_type TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, details_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_owner_created ON audit_events(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS billing_accounts (owner_id TEXT PRIMARY KEY, plan_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','past_due','paused','cancelled')), included_credits INTEGER NOT NULL DEFAULT 0 CHECK(included_credits >= 0), prepaid_credits INTEGER NOT NULL DEFAULT 0 CHECK(prepaid_credits >= 0), reserved_credits INTEGER NOT NULL DEFAULT 0 CHECK(reserved_credits >= 0), cycle_started_at TEXT NOT NULL, cycle_ends_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_reservations (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES billing_accounts(owner_id), idempotency_key TEXT NOT NULL, feature TEXT NOT NULL, estimated_credits INTEGER NOT NULL CHECK(estimated_credits > 0), actual_credits INTEGER CHECK(actual_credits >= 0), estimated_cost_microusd INTEGER NOT NULL CHECK(estimated_cost_microusd >= 0), actual_cost_microusd INTEGER CHECK(actual_cost_microusd >= 0), status TEXT NOT NULL CHECK(status IN ('reserved','settled','released','rejected')), created_at TEXT NOT NULL, settled_at TEXT, UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_usage_owner_created ON usage_reservations(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS usage_limits (owner_id TEXT PRIMARY KEY, daily_credit_limit INTEGER NOT NULL CHECK(daily_credit_limit >= 0), monthly_credit_limit INTEGER NOT NULL CHECK(monthly_credit_limit >= 0), max_request_cost_microusd INTEGER NOT NULL CHECK(max_request_cost_microusd >= 0), requests_per_minute INTEGER NOT NULL CHECK(requests_per_minute > 0), blocked_until TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_ledger (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES billing_accounts(owner_id), reservation_id TEXT REFERENCES usage_reservations(id), event_type TEXT NOT NULL CHECK(event_type IN ('reserve_included','reserve_prepaid','settle','release','reject')), credits INTEGER NOT NULL CHECK(credits >= 0), cost_microusd INTEGER NOT NULL DEFAULT 0 CHECK(cost_microusd >= 0), metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_usage_ledger_owner_created ON usage_ledger(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS provider_price_snapshots (id TEXT PRIMARY KEY, provider TEXT NOT NULL, model TEXT NOT NULL, input_microusd_per_million INTEGER NOT NULL CHECK(input_microusd_per_million >= 0), output_microusd_per_million INTEGER NOT NULL CHECK(output_microusd_per_million >= 0), credit_value_microusd INTEGER NOT NULL CHECK(credit_value_microusd > 0), effective_at TEXT NOT NULL, retired_at TEXT, UNIQUE(provider,model,effective_at));
